import{_ as e,o as t,c as a,a2 as d}from"./chunks/framework.CuUVYbLV.js";const q=JSON.parse('{"title":"图工作流","description":"用八个 graph_* 工具在运行时编排多代理工作流：建图、加节点、连边、运行、观测、审批门、有界循环与取消","frontmatter":{"title":"图工作流","description":"用八个 graph_* 工具在运行时编排多代理工作流：建图、加节点、连边、运行、观测、审批门、有界循环与取消"},"headers":[],"relativePath":"02-Guide/graph-workflows.md","filePath":"02-Guide/graph-workflows.md"}'),s={name:"02-Guide/graph-workflows.md"};function n(c,o,r,p,u,l){return t(),a("div",null,[...o[0]||(o[0]=[d(`<h1 id="图工作流-graph-workflows" tabindex="-1">图工作流（Graph Workflows） <a class="header-anchor" href="#图工作流-graph-workflows" aria-label="Permalink to &quot;图工作流（Graph Workflows）&quot;">​</a></h1><p>这一页回答「我要编排一件事，具体该按什么顺序调用哪些工具」。rolebox 的多代理编排是**命令式（imperative）**的：没有声明式的拓扑配置，你在运行时用八个 <code>graph_*</code> 工具把图搭出来，再交给图引擎执行。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05 用图引擎编排团队</a>｜相关：<a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a>｜<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>｜<a href="/rolebox-docs/04-Advanced/graph-declaration.html">图声明参考</a></p></blockquote><p>三个术语就地定义：<strong>图（graph，由 <code>graph_create</code> 创建并返回 <code>graph_id</code> 的编排容器）</strong>、<strong>节点（node，一次派发单元，形状是角色无关的 <code>{agent, prompt}</code> 元组）</strong>、<strong>边（edge，有向的 <code>from → to</code> 关系，既定义数据流也定义信号路由）</strong>。</p><h2 id="最小示例" tabindex="-1">最小示例 <a class="header-anchor" href="#最小示例" aria-label="Permalink to &quot;最小示例&quot;">​</a></h2><p>对角色说「把 coder 和 reviewer 串起来跑一遍」，它会依次调用五个工具：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_create   { &quot;name&quot;: &quot;mini-pipeline&quot; }</span></span>
<span class="line"><span>               → { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;name&quot;: &quot;mini-pipeline&quot;, &quot;created_at&quot;: &quot;...&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;id&quot;: &quot;coder&quot;,    &quot;agent&quot;: &quot;team--coder&quot;,    &quot;prompt&quot;: &quot;实现功能&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;coder&quot;, &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;created&quot;: true }</span></span>
<span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;id&quot;: &quot;reviewer&quot;, &quot;agent&quot;: &quot;team--reviewer&quot;, &quot;prompt&quot;: &quot;审查实现&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;reviewer&quot;, &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;created&quot;: true }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_edge { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;from&quot;: &quot;coder&quot;, &quot;to&quot;: &quot;reviewer&quot; }</span></span>
<span class="line"><span>               → { &quot;edge_id&quot;: &quot;coder-&gt;reviewer&quot;, &quot;from&quot;: &quot;coder&quot;, &quot;to&quot;: &quot;reviewer&quot;, &quot;type&quot;: &quot;always&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_run      { &quot;graph_id&quot;: &quot;g-7f3a&quot; }</span></span>
<span class="line"><span>               → { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;phase&quot;: &quot;executing&quot;,</span></span>
<span class="line"><span>                   &quot;active_nodes&quot;: [&quot;coder&quot;], &quot;pending_nodes&quot;: [&quot;reviewer&quot;] }</span></span></code></pre></div><p><code>graph_run</code> 只派发入度为零的<strong>根节点</strong>（这里是 <code>coder</code>）就立即返回，<strong>不阻塞</strong>。约定是<strong>调用后结束当前回合</strong>：引擎在全部节点结束时注入 <code>[GRAPH COMPLETE]</code>，在节点等待审批时注入 <code>[GRAPH BLOCKED]</code>。下一回合只回读一次结果，不要轮询：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_status   { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;include_output&quot;: true, &quot;format&quot;: &quot;tree&quot; }</span></span>
<span class="line"><span>               → 节点依赖树 + 每个节点的状态与产出</span></span></code></pre></div><p>八个工具按用途分四组：建图 <code>graph_create</code>；装配 <code>graph_add_node</code> / <code>graph_add_edge</code> / <code>graph_add_loop</code>；执行 <code>graph_run</code>；干预 <code>graph_status</code> / <code>graph_approve</code> / <code>graph_cancel</code>。每个工具的参数、返回格式与完整调用示例见<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>，全部工具的索引见<a href="/rolebox-docs/03-Reference/tool-catalog.html">工具目录</a>。</p><h2 id="建图-graph-create" tabindex="-1">建图：graph_create <a class="header-anchor" href="#建图-graph-create" aria-label="Permalink to &quot;建图：graph_create&quot;">​</a></h2><p>一次编排对应一张图。<code>graph_create</code> 接受人类可读的 <code>name</code>（日志里用它标识这张图）与可选的图级 <code>budget</code>（跨全部节点累计的 token 与成本上限），返回的 <code>graph_id</code> 是后续所有调用的寻址键：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_create { &quot;name&quot;: &quot;code-review&quot;, &quot;budget&quot;: { &quot;max_total_cost_usd&quot;: 5 } }</span></span>
<span class="line"><span>             → { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;name&quot;: &quot;code-review&quot;, &quot;created_at&quot;: &quot;...&quot; }</span></span></code></pre></div><ul><li><code>graph_status</code> 是唯一可以省略 <code>graph_id</code> 的工具：给它 <code>node_id</code> 或 <code>loop_id</code> 时它会自行推断归属图。</li><li>图级预算与节点级预算的分工，以及预算触顶后的行为，见<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>。</li><li>图只存在于内存注册表中；要跨会话查看它，用 <code>graph_status</code> 的 <code>scope</code> 参数（见下文「观测」）。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="加节点-graph-add-node" tabindex="-1">加节点：graph_add_node <a class="header-anchor" href="#加节点-graph-add-node" aria-label="Permalink to &quot;加节点：graph_add_node&quot;">​</a></h2><p>节点是一次派发：<code>id</code> 在图内唯一，<code>agent</code> 是承接它的角色标识（例如父角色 <code>team</code> 下的子代理 <code>team--coder</code>），<code>prompt</code> 是交给它的指令。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;id&quot;: &quot;tester&quot;, &quot;agent&quot;: &quot;team--tester&quot;,</span></span>
<span class="line"><span>                 &quot;prompt&quot;: &quot;运行测试并报告失败用例&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;tester&quot;, &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;created&quot;: true }</span></span></code></pre></div><ul><li><strong>汇聚</strong>：一个节点有多个上游时，用 <code>join</code> 决定何时开始——<code>{ &quot;strategy&quot;: &quot;all&quot; }</code>（缺省）、<code>&quot;any&quot;</code>，或 <code>{ &quot;strategy&quot;: &quot;quorum&quot;, &quot;quorum&quot;: 2 }</code>。<code>quorum</code> 是<strong>必需的应答数</strong>，不得超过该节点的入度。</li><li><strong>人工放行</strong>：<code>needs_approval: true</code> 让节点派发后停在 <code>blocked</code>，等待人工决策（见下文「审批门」）。</li><li><strong>韧性</strong>：节点级 <code>timeout_ms</code>（<code>0</code> 是有效值，表示关闭该节点的停滞看门狗）与 <code>max_retries</code>（节点升级后由引擎自动重试）。</li><li><strong>校验是原子的</strong>：非法节点会被整条拒绝，图保持不变。校验只看结构——<code>agent</code> 与 <code>prompt</code> 的语义不被解读，<code>agent</code> 是否真的可派发属于运行环境问题。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="连边-graph-add-edge" tabindex="-1">连边：graph_add_edge <a class="header-anchor" href="#连边-graph-add-edge" aria-label="Permalink to &quot;连边：graph_add_edge&quot;">​</a></h2><p>边决定工作怎么流转。<code>graph_add_edge</code> 给出 <code>from</code> / <code>to</code>，<code>type</code> 省略时默认 <code>always</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_add_edge { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;from&quot;: &quot;reviewer&quot;, &quot;to&quot;: &quot;tester&quot; }</span></span>
<span class="line"><span>               → { &quot;edge_id&quot;: &quot;reviewer-&gt;tester&quot;, &quot;from&quot;: &quot;reviewer&quot;, &quot;to&quot;: &quot;tester&quot;, &quot;type&quot;: &quot;always&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_edge { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;from&quot;: &quot;reviewer&quot;, &quot;to&quot;: &quot;coder&quot;,</span></span>
<span class="line"><span>                 &quot;type&quot;: &quot;on_signal&quot;, &quot;signal_filter&quot;: [&quot;revise_needed&quot;] }</span></span>
<span class="line"><span>               → { &quot;edge_id&quot;: &quot;reviewer-&gt;coder&quot;, &quot;from&quot;: &quot;reviewer&quot;, &quot;to&quot;: &quot;coder&quot;, &quot;type&quot;: &quot;on_signal&quot; }</span></span></code></pre></div><p>三种类型：</p><ul><li><code>always</code>——上游一有结果就激活，用于串行主干。</li><li><code>on_signal</code>——收到 <code>signal_filter</code> 列出的信号时激活；<strong>必须给 <code>signal_filter</code></strong>。上面的 <code>revise_needed</code> 回边是典型用法：它把已经完成的上游节点重新拉回就绪，形成评审返工。</li><li><code>on_condition</code>——<code>condition</code> 命名的条件评估为真时激活；<strong>必须给 <code>condition</code></strong>，且名字必须来自已注册的条件词汇表，否则结构校验直接拒绝。</li></ul><p>边的其他字段是数据透传（<code>data_passthrough_include</code> / <code>data_passthrough_exclude</code> / <code>data_passthrough_max_chars</code>）与升级重试（<code>retry</code>）。参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><p>一条硬约束：<code>needs_approval: true</code> 的节点<strong>只能</strong>有 <code>on_signal</code> 或 <code>on_condition</code> 出边。给它一条 <code>always</code> 出边会让图在人工决策之前就继续前进，因此会被校验拒绝。</p><h2 id="运行-graph-run-是非阻塞的" tabindex="-1">运行：graph_run 是非阻塞的 <a class="header-anchor" href="#运行-graph-run-是非阻塞的" aria-label="Permalink to &quot;运行：graph_run 是非阻塞的&quot;">​</a></h2><p><code>graph_run</code> 派发所有就绪根节点后立即返回 <code>phase</code> / <code>active_nodes</code> / <code>pending_nodes</code>，不等待结果。正确用法只有三步：</p><ol><li><strong>调用 <code>graph_run</code>，然后结束当前回合。</strong></li><li>等待引擎注入的系统提醒：所有节点结束是 <code>[GRAPH COMPLETE]</code>，有节点等待审批是 <code>[GRAPH BLOCKED]</code>。</li><li><strong>下一回合回读一次</strong> <code>graph_status(graph_id, include_output: true)</code>；只有在提醒始终没有到达时才把 <code>graph_status</code> 当作兜底轮询。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_run    { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;dry_run&quot;: true }</span></span>
<span class="line"><span>             → { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;phase&quot;: &quot;validating&quot;, &quot;active_nodes&quot;: [], &quot;pending_nodes&quot;: [],</span></span>
<span class="line"><span>                 &quot;dry_run&quot;: true, &quot;validation&quot;: { ... } }</span></span></code></pre></div><ul><li><code>dry_run: true</code> 只做 <code>execution</code> 级别的结构校验并返回 <code>validation</code>，不派发任何节点——适合在真正跑之前验证一张图。</li><li>给 <code>node_id</code> 可以只重跑某个节点；再加 <code>retry: true</code> 表示重试，<code>modify_prompt</code> 可以在重试时替换该节点的指令。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="观测-graph-status" tabindex="-1">观测：graph_status <a class="header-anchor" href="#观测-graph-status" aria-label="Permalink to &quot;观测：graph_status&quot;">​</a></h2><p><code>graph_status</code> 是统一的可观测端点。不给目标时它列出全部图；<code>format</code> 取 <code>summary</code>（表格）、<code>tree</code>（节点依赖树）或 <code>json</code>（机器可读快照）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_status { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;format&quot;: &quot;tree&quot; }</span></span>
<span class="line"><span>             → code-review (executing)</span></span>
<span class="line"><span>               ├─ coder      completed</span></span>
<span class="line"><span>               └─ reviewer   running</span></span></code></pre></div><p>按用途挑参数：</p><ul><li><strong>范围</strong>：<code>scope: &quot;session&quot;</code>（默认，只读内存注册表）、<code>&quot;persisted&quot;</code>（读磁盘上的引擎状态，跨会话视图）、<code>&quot;all&quot;</code>（合并两者，冲突时注册表优先）。</li><li><strong>定位</strong>：<code>node_id</code> / <code>loop_id</code> 查询单个节点或循环组；<code>status</code> / <code>agent</code> / <code>query</code> / <code>from_date</code> / <code>to_date</code> 过滤；<code>limit</code> / <code>offset</code> / <code>tail</code> / <code>max_chars</code> 分页与截断；<code>depth</code> 裁剪树深度；<code>group_by</code> 按小时 / 天 / 角色聚合已完成节点。</li><li><strong>展开内容</strong>：<code>include_output</code>（节点产出）、<code>include_progress</code>、<code>include_budget</code>、<code>include_metrics</code>、<code>include_loops</code> 与 <code>include_history</code> / <code>round</code>（循环组与逐回合历史）、<code>include_checkpoint</code>、<code>include_artifacts</code>、<code>include_evidence</code>、<code>include_liveness</code>、<code>stream</code> / <code>since</code>（信号事件历史）。</li><li><strong>落盘</strong>：<code>export_path</code> 原子写出——有 <code>node_id</code> 时写该节点的结果文本，<code>include_metrics</code> 时写指标 JSON，否则写图声明的 YAML。</li></ul><p>空结果一律渲染为诚实的空提示（例如 <code>no pending approvals</code>），不会编造行。</p><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="审批门-needs-approval-与-graph-approve" tabindex="-1">审批门：needs_approval 与 graph_approve <a class="header-anchor" href="#审批门-needs-approval-与-graph-approve" aria-label="Permalink to &quot;审批门：needs_approval 与 graph_approve&quot;">​</a></h2><p>给节点设 <code>needs_approval: true</code>，它派发后进入 <code>blocked</code>，下游派发暂停，引擎注入 <code>[GRAPH BLOCKED]</code> 把编排者唤醒。**人工在环（HITL，human-in-the-loop）**的完整流程是「发现 → 决策」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 1) 发现：列出所有正在等待人工的节点</span></span>
<span class="line"><span>graph_status  { &quot;pending_approvals&quot;: true }</span></span>
<span class="line"><span>              → graph g-7f3a · node final-gate · blocked since 2026-09-17T06:12:03Z</span></span>
<span class="line"><span>                approval_payload: { &quot;summary&quot;: &quot;评审通过，请求放行&quot; }</span></span>
<span class="line"><span>                → graph_approve { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;node_id&quot;: &quot;final-gate&quot;, &quot;action&quot;: &quot;approve&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2) 决策：批准（或带反馈拒绝）</span></span>
<span class="line"><span>graph_approve { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;node_id&quot;: &quot;final-gate&quot;,</span></span>
<span class="line"><span>                &quot;action&quot;: &quot;approve&quot;, &quot;payload&quot;: { &quot;released&quot;: true } }</span></span>
<span class="line"><span>              → { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;node_id&quot;: &quot;final-gate&quot;, &quot;action&quot;: &quot;approve&quot;,</span></span>
<span class="line"><span>                  &quot;node_status&quot;: &quot;completed&quot;, &quot;phase&quot;: &quot;executing&quot;, &quot;applied&quot;: true }</span></span></code></pre></div><ul><li><code>graph_status</code> 的 <code>pending_approvals: true</code> 是专门的「等待人工」视图：它跨当前 <code>scope</code> 列出每一个阻塞中的 <code>needs_approval</code> 节点，每行带归属图、阻塞起始时间、截断后的 <code>approval_payload</code> 摘要，以及一条<strong>可直接粘贴</strong>的 <code>graph_approve</code> 调用。</li><li><code>approve</code> 解除门禁（<code>blocked → completed</code>）并沿 <code>answer</code> 边把 <code>payload</code> 传给下游；<code>reject</code> 在该节点属于循环组时带 <code>reason</code> 重新进入，否则把它升级。</li><li>两个动作都<strong>幂等</strong>：对已经解决的节点再次决策是空操作，返回值里的 <code>applied: false</code> 会如实说明这一点。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="有界循环-graph-add-loop" tabindex="-1">有界循环：graph_add_loop <a class="header-anchor" href="#有界循环-graph-add-loop" aria-label="Permalink to &quot;有界循环：graph_add_loop&quot;">​</a></h2><p>图里的每个有向环都必须被一个显式声明的<strong>循环组（loop group）<strong>覆盖：<code>graph_add_loop</code> 用 <code>nodes</code> 列出构成该环的节点，用 <code>max_traversals</code> 给出</strong>硬性遍历上限</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_add_loop { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;id&quot;: &quot;revise-loop&quot;,</span></span>
<span class="line"><span>                 &quot;nodes&quot;: [&quot;coder&quot;, &quot;reviewer&quot;], &quot;max_traversals&quot;: 3 }</span></span>
<span class="line"><span>               → { &quot;loop_id&quot;: &quot;revise-loop&quot;, &quot;graph_id&quot;: &quot;g-7f3a&quot;,</span></span>
<span class="line"><span>                   &quot;nodes&quot;: [&quot;coder&quot;, &quot;reviewer&quot;], &quot;max_traversals&quot;: 3 }</span></span></code></pre></div><ul><li><code>max_traversals</code> 是整数且最小为 1。触顶后 <code>revise_needed</code> 不再回环，成员节点升级为 <code>escalate</code>，并带上结构化载荷（退出原因、未解决项、已消耗的遍历次数）。</li><li>循环的三种退出方式：收敛（收敛节点发出 <code>answer</code>，自然结束且不消耗遍历次数）、触顶升级、停滞升级（连续两次遍历的收敛输出完全相同）。完整结果集合见<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>。</li><li><code>mode</code> 只有 <code>inherit</code> 一种有效取值（省略即默认）：各回合在同一份引擎状态内重新派发。<code>mode: &quot;fresh&quot;</code> <strong>未实现</strong>，传入会返回显式错误；需要逐回合会话隔离时，改为<strong>每个回合用一张独立的图</strong>。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="取消-graph-cancel" tabindex="-1">取消：graph_cancel <a class="header-anchor" href="#取消-graph-cancel" aria-label="Permalink to &quot;取消：graph_cancel&quot;">​</a></h2><p><code>graph_cancel</code> 是人工监控与干预用的控制面——<strong>不要</strong>用它让代理自我取消正在运行的工作流。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_cancel { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;loop_id&quot;: &quot;revise-loop&quot; }</span></span>
<span class="line"><span>             → { &quot;cancelled&quot;: [&quot;coder&quot;, &quot;reviewer&quot;], &quot;graph_id&quot;: &quot;g-7f3a&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_cancel { &quot;graph_id&quot;: &quot;g-7f3a&quot;, &quot;node_id&quot;: &quot;tester&quot;, &quot;cascade&quot;: true }</span></span>
<span class="line"><span>             → { &quot;cancelled&quot;: [&quot;tester&quot;, &quot;doc-writer&quot;], &quot;graph_id&quot;: &quot;g-7f3a&quot; }</span></span></code></pre></div><ul><li>不给 <code>node_id</code> / <code>loop_id</code> 时取消整张图；给 <code>node_id</code> 只取消该节点，给 <code>loop_id</code> 则解析为它的完整成员集。</li><li><code>cascade: true</code> 让取消沿边向前闭包，把传递下游的节点一并取消。默认值：循环目标为 <code>true</code>，裸 <code>node_id</code> 为 <code>false</code>，整图取消时忽略。</li><li>返回值是引擎<strong>实际</strong>取消的节点 id 集合，而不是猜测。</li></ul><p>参数明细：<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li><strong><code>on_signal</code> 边漏了 <code>signal_filter</code></strong>：工具直接拒绝该边（<code>type &quot;on_signal&quot; but no &quot;signal_filter&quot; was provided</code>）。</li><li><strong><code>on_condition</code> 用了未注册的条件名</strong>：结构校验在写入时拒绝；空 <code>condition</code> 同样被拒绝。</li><li><strong>给 <code>needs_approval</code> 节点连了 <code>always</code> 出边</strong>：校验拒绝——那样图会在人工决策前继续前进。</li><li><strong>加了回边却没声明循环组</strong>：增量建图阶段（<code>construct</code>）只是警告，但 <code>graph_run</code> 前的 <code>execution</code> 校验会把没有 <code>revise_needed</code> 回边的未覆盖环升级为致命错误，因为这种环永远无法激活。</li><li><strong>循环组的节点集合本身不成环</strong>：声明一个无环的「循环」是结构错误。</li><li><strong><code>quorum</code> 大于该节点入度</strong>：拒绝——那是一个永远无法满足的 join。节点还没有入边时，这个上界检查会延后，以支持增量建图。</li><li><strong><code>mode: &quot;fresh&quot;</code></strong>：返回显式错误，改用每回合一张图。</li><li><strong><code>graph_run</code> 之后不结束回合，改用轮询</strong>：与工具契约相反。引擎会注入 <code>[GRAPH COMPLETE]</code> / <code>[GRAPH BLOCKED]</code>，回读一次即可，轮询只是提醒未到时的兜底。</li><li><strong>节点或循环组 <code>id</code> 重复</strong>：在同一张图内 <code>id</code> 必须唯一，重复会被拒绝。</li></ul><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><blockquote><p>自 v1.0.0 起，多代理编排由命令式 <code>graph_*</code> 工具与 v2 图引擎承载。</p></blockquote><ul><li><code>role.yaml</code> 的角色级 <code>graph:</code> 键目前只是向前兼容的语法占位：解析器识别 <code>graph.orchestration</code> 并记录一条「已识别但未接线」的警告，它<strong>没有</strong>任何编排效果。字段说明见 <a href="/rolebox-docs/03-Reference/role-yaml.html">role.yaml 参考</a>，声明文档格式见<a href="/rolebox-docs/04-Advanced/graph-declaration.html">图声明参考</a>。</li><li>若你的角色仍带着已移除的声明式协作配置块，迁移写法见<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>与<a href="/rolebox-docs/02-Guide/collaboration-graph.html">协作图</a>。</li><li>本页只讲「怎么调用工具」。节点状态机、join 评估、信号传播与级联取消的实现语义见<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>与<a href="/rolebox-docs/04-Advanced/runtime-behavior.html">运行时行为</a>；选型（该用哪种拓扑）见<a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a>。</li></ul>`,60)])])}const g=e(s,[["render",n]]);export{q as __pageData,g as default};
